import pLimit, {limitFunction} from './index.js';

const delay = milliseconds => new Promise(resolve => {
	setTimeout(resolve, milliseconds);
});

const deferred = () => {
	let resolve;
	let reject;
	const promise = new Promise((innerResolve, innerReject) => { // eslint-disable-line promise/param-names
		resolve = innerResolve;
		reject = innerReject;
	});
	return {promise, resolve, reject};
};

test('onIdle resolves immediately when already idle', async t => {
	const limit = pLimit(1);
	await limit.onIdle();
	t.pass();
});

test('onIdle resolves after running and queued work settles', async t => {
	const limit = pLimit(2);
	let completed = 0;

	const job = async () => {
		await delay(10);
		completed++;
	};

	for (let index = 0; index < 5; index++) {
		limit(job);
	}

	t.is(limit.activeCount, 2);
	t.is(limit.pendingCount, 3);

	await limit.onIdle();
	t.is(completed, 5);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle supports multiple concurrent waiters', async t => {
	const limit = pLimit(1);
	const gate = deferred();

	limit(async () => gate.promise);

	const order = [];
	const first = limit.onIdle().then(() => order.push('first'));
	const second = limit.onIdle().then(() => order.push('second'));

	let resolved = false;
	void Promise.all([first, second]).then(() => {
		resolved = true;
	});

	await delay(20);
	t.false(resolved);

	gate.resolve();
	await Promise.all([first, second]);
	t.true(resolved);
	t.deepEqual(order.sort(), ['first', 'second']);
});

test('onIdle resolves when jobs reject', async t => {
	const limit = pLimit(2);

	limit(async () => {
		await delay(5);
		throw new Error('rejected job');
	});
	limit(async () => {
		await delay(5);
		return 'ok';
	});

	await limit.onIdle();
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('reserved slots count as active for onIdle', async t => {
	const limit = pLimit(1);
	const gate = deferred();

	const promise = limit(async () => gate.promise);

	await delay(10);
	let idle = false;
	void limit.onIdle().then(() => {
		idle = true;
	});

	await delay(10);
	t.false(idle);
	t.is(limit.activeCount, 1);

	gate.resolve();
	await promise;
	await limit.onIdle();
	t.true(idle);
});

test('onIdle does not resolve early when a finishing job enqueues another job', async t => {
	const limit = pLimit(1);
	let secondStarted = false;
	let secondFinished = false;

	const second = deferred();

	const first = limit(async () => {
		// The last active job queues another job before finishing.
		void limit(async () => {
			secondStarted = true;
			await second.promise;
			secondFinished = true;
		});
	});

	void first;

	let idleEarly = false;
	const idlePromise = limit.onIdle().then(() => {
		idleEarly = true;
	});

	// Give the queue time to churn through the first job.
	await delay(30);
	t.false(idleEarly);
	t.true(secondStarted);

	second.resolve();
	await idlePromise;
	t.true(secondFinished);
});

test('clearQueue releases onIdle waiters when no jobs are active (rejectOnClear: false)', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: false});
	const gate = deferred();

	// This discarded promise stays unresolved forever.
	const discarded = limit(async () => gate.promise);
	t.not(discarded, undefined);

	const queued = limit(async () => 'never runs');
	t.not(queued, undefined);

	await delay(10);

	let idleResolved = false;
	const idlePromise = limit.onIdle().then(() => {
		idleResolved = true;
	});

	limit.clearQueue();
	await idlePromise;
	t.true(idleResolved);
	t.is(limit.pendingCount, 0);
});

test('clearQueue releases onIdle waiters with rejectOnClear: true', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: true});
	const gate = deferred();

	const running = limit(async () => gate.promise);
	const pendingPromises = [limit(async () => 'never runs'), limit(async () => 'never runs')];

	await delay(10);

	let idleResolved = false;
	const idlePromise = limit.onIdle().then(() => {
		idleResolved = true;
	});

	t.false(idleResolved);

	limit.clearQueue();

	// Waiters stay idle until the active job finishes too.
	await delay(10);
	t.false(idleResolved);

	gate.resolve();
	await running;
	await idlePromise;
	t.true(idleResolved);

	await t.throwsAsync(Promise.all(pendingPromises), {name: 'AbortError'});
});

test('clearQueue on an already empty limiter resolves onIdle immediately', async t => {
	const limit = pLimit(1);
	limit.clearQueue();
	await limit.onIdle();
	t.pass();
});

test('limitFunction wrapper exposes onIdle', async t => {
	const gate = deferred();
	let calls = 0;

	const limited = limitFunction(async () => {
		calls++;
		await gate.promise;
		return calls;
	}, {concurrency: 1});

	t.is(typeof limited.onIdle, 'function');

	const first = limited();
	const second = limited();

	await delay(10);
	t.is(calls, 1);

	let idle = false;
	void limited.onIdle().then(() => {
		idle = true;
	});

	await delay(10);
	t.false(idle);

	gate.resolve();
	await Promise.all([first, second]);
	await limited.onIdle();
	t.true(idle);
	t.is(calls, 2);
});

test('limitFunction onIdle resolves immediately when idle and after clearQueue', async t => {
	const gate = deferred();

	const limited = limitFunction(async () => gate.promise, {concurrency: 1});

	await limited.onIdle();

	const first = limited();
	t.not(first, undefined);
	const second = limited();
	t.not(second, undefined);

	await delay(10);

	let idle = false;
	const idlePromise = limited.onIdle().then(() => {
		idle = true;
	});

	limited.clearQueue();
	await delay(10);
	t.false(idle); // The still-running first call keeps it busy.

	gate.resolve();
	await first;
	await idlePromise;
	t.true(idle);
});

test('FIFO order is preserved alongside onIdle usage', async t => {
	const limit = pLimit(1);
	const order = [];

	const makeJob = name => async () => {
		order.push(name);
		await delay(1);
	};

	const promises = [
		limit(makeJob('a')),
		limit(makeJob('b')),
		limit(makeJob('c')),
	];

	const idlePromise = limit.onIdle();

	await Promise.all(promises);
	await idlePromise;

	t.deepEqual(order, ['a', 'b', 'c']);
});

test('raising concurrency wakes the queue and onIdle still waits for everything', async t => {
	const limit = pLimit(1);
	let completed = 0;

	const job = async () => {
		await delay(5);
		completed++;
	};

	for (let index = 0; index < 4; index++) {
		limit(job);
